1708	    ///     // record.
1709	    ///     assert_eq!(pos.byte(), 51);
1710	    ///     assert_eq!(pos.line(), 3);
1711	    ///     assert_eq!(pos.record(), 2);
1712	    ///     Ok(())
1713	    /// }
