38	impl PartialEq for ByteRecord {
39	    fn eq(&self, other: &ByteRecord) -> bool {
40	        if self.len() != other.len() {
41	            return false;
42	        }
43	        self.iter().zip(other.iter()).all(|e| e.0 == e.1)
44	    }
45	}
