178	    /// # fn main() { example().unwrap() }
179	    /// fn example() -> Result<(), Box<dyn Error>> {
180	    ///     let record = ByteRecord::from(vec![
181	    ///         "Boston", "United States", "4628910",
182	    ///     ]);
183	    ///
