201	    /// ```
202	    /// use std::error::Error;
203	    ///
204	    /// use csv::ByteRecord;
205	    /// use serde::Deserialize;
206	    ///
207	    /// #[derive(Deserialize)]
208	    /// struct Row {
209	    ///     city: String,
210	    ///     country: String,
211	    ///     population: u64,
212	    /// }
213	    ///
