404	    ///
405	    /// # Example
406	    ///
407	    /// ```
408	    /// use std::error::Error;
409	    ///
410	    /// use csv::{ByteRecord, ReaderBuilder};
411	    ///
412	    /// # fn main() { example().unwrap(); }
413	    /// fn example() -> Result<(), Box<dyn Error>> {
414	    ///     let mut record = ByteRecord::new();
