515	    /// Retrieve the underlying parts of a byte record.
516	    #[inline]
517	    pub(crate) fn as_parts(&mut self) -> (&mut Vec<u8>, &mut Vec<usize>) {
518	        let inner = &mut *self.0;
519	        (&mut inner.fields, &mut inner.bounds.ends)
520	    }
