858	fn trim_ascii(bytes: &[u8]) -> &[u8] {
859	    trim_ascii_start(trim_ascii_end(bytes))
860	}
861	
862	fn trim_ascii_start(mut bytes: &[u8]) -> &[u8] {
863	    while let [first, rest @ ..] = bytes {
864	        if first.is_ascii_whitespace() {
865	            bytes = rest;
866	        } else {
867	            break;
868	        }
869	    }
870	    bytes
871	}
872	
873	fn trim_ascii_end(mut bytes: &[u8]) -> &[u8] {
874	    while let [rest @ .., last] = bytes {
875	        if last.is_ascii_whitespace() {
876	            bytes = rest;
877	        } else {
878	            break;
879	        }
880	    }
881	    bytes
882	}
