use std::{
    fmt, io,
    iter::FromIterator,
    ops::{self, Range},
    result, str,
};

use serde_core::de::Deserialize;

use crate::{
    byte_record::{ByteRecord, ByteRecordIter, Position},
    deserializer::deserialize_string_record,
    error::{Error, ErrorKind, FromUtf8Error, Result},
    reader::Reader,
