use csv_core::{Reader, ReaderBuilder, ReadRecordResult::*};

fn run(nfa: bool, chunks: &[&[u8]]) {
    let mut b = ReaderBuilder::new();
    b.nfa(nfa);
    let mut rdr = b.build();
    let mut record = vec![0u8; 64];
    let mut ends = [0usize; 10];
    let (mut outpos, mut endpos) = (0, 0);
    let mut records = vec![];
    for ch in chunks.iter().chain([&b""[..]].iter()).chain([&b""[..]].iter()) {
        let (res, nin, nout, nend) = rdr.read_record(ch, &mut record[outpos..], &mut ends[endpos..]);
        outpos += nout; endpos += nend;
        eprintln!("chunk={:?} res={:?} nin={} nout={} nend={} outpos={} endpos={}", std::str::from_utf8(ch).unwrap_or("?"), res, nin, nout, nend, outpos, endpos);
        if res == Record {
            let mut start = 0; let mut fs = vec![];
            for &e in &ends[..endpos] { fs.push(String::from_utf8_lossy(&record[start..e]).to_string()); start = e; }
            records.push(fs); outpos = 0; endpos = 0;
        }
    }
    println!("nfa={} -> {:?}", nfa, records);
}

#[test]
fn nfa_chunked() {
    let chunks: Vec<&[u8]> = "abc,def\nghi,jkl\n".as_bytes().chunks(2).collect();
    run(false, &chunks);
    run(true, &chunks);
}
