#[derive(Clone, Debug)]
pub struct Reader {
    /// A table-based DFA for parsing CSV.
    dfa: Dfa,
    /// The current DFA state, if the DFA is used.
    dfa_state: DfaState,
    /// The current NFA state, if the NFA is used.
    nfa_state: NfaState,
    /// The delimiter that separates fields.
    delimiter: u8,
    /// The terminator that separates records.
    term: Terminator,
    /// The quotation byte.
    quote: u8,
    /// Whether to recognize escaped quotes.
    escape: Option<u8>,
    /// Whether to recognized doubled quotes.
    double_quote: bool,
    /// If enabled, lines beginning with this byte are ignored.
    comment: Option<u8>,
    /// If enabled (the default), then quotes are respected. When disabled,
    /// quotes are not treated specially.
    quoting: bool,
    /// Whether to use the NFA for parsing.
    ///
    /// Generally this is for debugging. There's otherwise no good reason
    /// to avoid the DFA.
    use_nfa: bool,
    /// The current line number.
    line: u64,
    /// The status of UTF-8 BOM detection at the start of the stream.
    bom_state: BomState,
    /// Candidate BOM bytes received from the caller but not yet handed to
    /// the state machine.
    ///
    /// While `bom_state` is `Checking`, these store the unmatched prefix of
    /// the BOM (`\xEF` or `\xEF\xBB`) when a read boundary happens to fall
    /// in the middle of the BOM. If the BOM is ruled out, these bytes are
    /// replayed to the state machine as ordinary data instead of being
    /// swallowed.
    bom_buf: [u8; 2],
    /// The number of candidate BOM bytes stored in `bom_buf` (0, 1 or 2).
    bom_len: usize,
    /// The replay position inside `bom_buf` once the BOM has been ruled out.
    bom_pos: usize,
    /// The current position in the output buffer when reading a record.
    output_pos: usize,
}

impl Default for Reader {
    fn default() -> Reader {
        Reader {
            dfa: Dfa::new(),
            dfa_state: DfaState::start(),
            nfa_state: NfaState::StartRecord,
            delimiter: b',',
            term: Terminator::default(),
            quote: b'"',
            escape: None,
            double_quote: true,
            comment: None,
            quoting: true,
            use_nfa: false,
            line: 1,
            bom_state: BomState::Checking,
            bom_buf: [0; 2],
            bom_len: 0,
            bom_pos: 0,
            output_pos: 0,
        }
    }
}

