pub fn read_field(
    &mut self,
    input: &[u8],
    output: &mut [u8],
) -> (ReadFieldResult, usize, usize) {
    let preface = self.bom_preprocess(input);
    // While the BOM is still only a partial prefix, bytes may be absorbed
    // without ever reaching the parser.
    if preface.pending {
        return (ReadFieldResult::InputEmpty, input.len(), 0);
    }
    let (mut nin, mut nout) = (preface.start, 0);
    // Replay any bytes held from earlier reads that were ruled out as a
    // BOM. They are ordinary data, but they never count toward `nin` of
    // the current call since they were not received in this call.
    loop {
        if self.bom_pos >= self.bom_len {
            break;
        }
        let (res, rn, on) = {
            let part = &preface.held[self.bom_pos..self.bom_len];
            self.read_field_once(part, &mut output[nout..])
        };
        self.bom_pos += rn;
        nout += on;
        if self.bom_pos >= self.bom_len {
            self.bom_len = 0;
            self.bom_pos = 0;
        }
        match res {
            ReadFieldResult::InputEmpty => continue,
            _ => return (res, nin, nout),
        }
    }
    let cur = &input[preface.start..];
    // If the BOM ended exactly at the end of this call's input, do not run
    // the final transition yet. The caller signals real end of stream by
    // subsequently passing an empty input.
    if cur.is_empty() && preface.start > 0 {
        return (ReadFieldResult::InputEmpty, nin, nout);
    }
    let (res, rn, on) = self.read_field_once(cur, &mut output[nout..]);
    (res, nin + rn, nout + on)
}

/// Dispatch a single chunk to either the NFA or DFA field parser.
#[inline(always)]
fn read_field_once(
    &mut self,
    input: &[u8],
    output: &mut [u8],
) -> (ReadFieldResult, usize, usize) {
    if self.use_nfa {
        self.read_field_nfa(input, output)
    } else {
        self.read_field_dfa(input, output)
    }
}

