pub fn read_field(
    &mut self,
    input: &[u8],
    output: &mut [u8],
) -> (ReadFieldResult, usize, usize) {
    let step = self.bom_preprocess(input);
    if step.absorb {
        // The whole chunk is an undecided prefix of the BOM.
        return (ReadFieldResult::InputEmpty, input.len(), 0);
    }
    let mut nin = step.nin_base;
    let mut nout = 0;
    // Replay bytes held by earlier reads that have now been ruled out as
    // a BOM. They are ordinary data and never count toward `nin` of the
    // current call.
    let mut pos = step.replay.start;
    while pos < step.replay.end {
        let (res, rn, on) =
            self.read_field_once(&BOM[pos..step.replay.end], output);
        pos += rn;
        nout += on;
        match res {
            ReadFieldResult::InputEmpty => continue,
            _ => {
                self.bom_pos = pos;
                self.bom_len = step.replay.end;
                return (res, nin, nout);
            }
        }
    }
    self.bom_pos = 0;
    self.bom_len = 0;
    // A non-empty chunk consisting of exactly the confirmed BOM must not
    // trigger the final transition. The caller signals the real end of
    // stream by subsequently passing an empty input.
    if !input.is_empty() && step.data.is_empty() {
        return (ReadFieldResult::InputEmpty, nin, nout);
    }
    let (res, rn, on) = self.read_field_once(step.data, output);
    (res, nin + rn, nout + on)
}

