pub fn read_field(
    &mut self,
    input: &[u8],
    output: &mut [u8],
) -> (ReadFieldResult, usize, usize) {
    // The BOM preprocessing decides what to feed the parser and how many
    // caller bytes are accounted for up front.
    let mut plan = self.bom_plan(input);
    if plan.absorb {
        // The entire chunk is an undecided prefix of the BOM.
        return (ReadFieldResult::InputEmpty, input.len(), 0);
    }
    let mut nin = plan.nin;
    let mut nout = 0;
    // Replay any bytes from earlier reads that are now known not to be a
    // BOM. They are ordinary data, but never count toward `nin` of this
    // call since they were not received now.
    while !plan.prefix.is_empty() {
        let (res, rn, on) =
            self.read_field_once(plan.prefix, &mut output[nout..]);
        plan.prefix = &plan.prefix[rn..];
        nout += on;
        if !matches!(res, ReadFieldResult::InputEmpty) {
            // Remember what is left to replay for a subsequent call.
            self.bom_save_remaining(&plan.prefix);
            return (res, nin, nout);
        }
    }
    self.bom_clear_replay();
    // A non-empty chunk made up of exactly the (confirmed) BOM must not be
    // reported as the end of the stream. The caller signals the real end by
    // subsequently passing an empty input.
    if !input.is_empty() && plan.data.is_empty() {
        return (ReadFieldResult::InputEmpty, nin, nout);
    }
    let (res, rn, on) =
        self.read_field_once(plan.data, &mut output[nout..]);
    (res, nin + rn, nout + on)
}

