    // absorbed; nothing is emitted yet.
    if let Bom::Check(_) = self.bom {
        return (ReadFieldResult::InputEmpty, nin, 0);
    }
    // Replay bytes that have been ruled out as a BOM. These are ordinary
    // data and never count toward `nin` of the current call.
    if let Bom::Replay(_) = self.bom {
        let mut replay = self.bom_replay();
        loop {
            if replay.pos >= replay.len {
                self.bom = Bom::Done;
                break;
