            return (ReadFieldResult::InputEmpty, nin, nout);
        }
        let (res, rn, on) =
            self.read_field_once(data, &mut output[nout..]);
        return (res, nin + rn, nout + on);
    }
    // Empty input: run the final transition exactly once.
    let (res, rn, on) = self.read_field_once(&[], &mut output[nout..]);
