use csv_core::{Reader, ReaderBuilder, ReadFieldResult, ReadRecordResult};

// Parse by field, feeding input in fixed-size chunks and using tiny output.
fn by_field(nfa: bool, data: &[u8], chunk: usize, outcap: usize) -> Vec<Vec<Vec<u8>>> {
    let mut b = ReaderBuilder::new();
    b.nfa(nfa);
    let mut rdr = b.build();
    let mut records = vec![];
    let mut row = vec![];
    let mut field = vec![];
    let mut i = 0;
    let mut done = false;
    while !done {
        let end = (i + chunk).min(data.len());
        let mut inp = &data[i..end];
        let mut out = vec![0u8; outcap];
        let (res, nin, nout) = rdr.read_field(inp, &mut out);
        assert!(nin <= inp.len());
        i += nin;
        inp = &inp[nin..];
        field.extend_from_slice(&out[..nout]);
        match res {
            ReadFieldResult::InputEmpty => {
                if i == data.len() {
                    // signal EOF with empty input
                    let (res2, _, nout2) = rdr.read_field(&[], &mut out);
                    field.extend_from_slice(&out[..nout2]);
                    match res2 {
                        ReadFieldResult::InputEmpty => panic!("unexpected IE after empty"),
                        ReadFieldResult::OutputFull => panic!("of"),
                        ReadFieldResult::Field { record_end } => {
                            row.push(std::mem::take(&mut field));
                            if record_end { records.push(std::mem::take(&mut row)); }
                        }
                        ReadFieldResult::End => {
                            assert!(field.is_empty());
                            assert!(row.is_empty());
                            done = true;
                        }
                    }
                }
            }
            ReadFieldResult::OutputFull => {}
            ReadFieldResult::Field { record_end } => {
                row.push(std::mem::take(&mut field));
                if record_end { records.push(std::mem::take(&mut row)); }
            }
            ReadFieldResult::End => {
                done = true;
            }
        }
    }
    records
}

fn by_record(nfa: bool, data: &[u8], chunk: usize, outcap: usize, endcap: usize)
    -> Vec<Vec<Vec<u8>>>
{
    let mut b = ReaderBuilder::new();
    b.nfa(nfa);
    let mut rdr = b.build();
    let mut outbuf = vec![];
    let mut ends = vec![];
    let mut records = vec![];
    let mut i = 0;
    let mut done = false;
    while !done {
        let end = (i + chunk).min(data.len());
        let mut out = vec![0u8; outcap];
        let mut es = vec![0usize; endcap];
        let (res, nin, nout, nend) =
            rdr.read_record(&data[i..end], &mut out, &mut es);
        assert!(nin <= end - i);
        i += nin;
        outbuf.extend_from_slice(&out[..nout]);
        ends.extend_from_slice(&es[..nend]);
        match res {
            ReadRecordResult::InputEmpty => {
                if i == data.len() {
                    let (res2, _, nout2, nend2) =
                        rdr.read_record(&[], &mut out, &mut es);
                    outbuf.extend_from_slice(&out[..nout2]);
                    ends.extend_from_slice(&es[..nend2]);
                    finish_rec(res2, &mut outbuf, &mut ends, &mut records, &mut done);
                }
            }
            ReadRecordResult::OutputFull | ReadRecordResult::OutputEndsFull => {}
            ReadRecordResult::Record => {
                finish_rec(ReadRecordResult::Record, &mut outbuf, &mut ends, &mut records, &mut done);
            }
            ReadRecordResult::End => done = true,
        }
    }
    records
}

fn finish_rec(
    res: ReadRecordResult,
    outbuf: &mut Vec<u8>,
    ends: &mut Vec<usize>,
    records: &mut Vec<Vec<Vec<u8>>>,
    done: &mut bool,
) {
    match res {
        ReadRecordResult::Record => {
            let mut row = vec![];
            let mut start = 0;
            for &e in ends.iter() {
                row.push(outbuf[start..e].to_vec());
                start = e;
            }
            records.push(row);
            outbuf.clear();
            ends.clear();
        }
        ReadRecordResult::End => *done = true,
        _ => panic!("unexpected {:?}", res),
    }
}

fn show(recs: &[Vec<Vec<u8>>]) -> Vec<Vec<String>> {
    recs.iter().map(|r| r.iter().map(|f| String::from_utf8_lossy(f).to_string()).collect()).collect()
}

#[test]
fn split_bom_field() {
    let data = b"\xef\xbb\xbfname,value\r\n\xe7\x94\xb2,7\r\n";
    let expected = vec![vec!["name".to_string(), "value".to_string()],
                        vec!["甲".to_string(), "7".to_string()]];
    for &nfa in &[false, true] {
        for chunk in 1..=8 {
            for outcap in 1..=6 {
                let got = by_field(nfa, data, chunk, outcap);
                assert_eq!(show(&got), expected, "field nfa={} chunk={} outcap={}", nfa, chunk, outcap);
                let got = by_record(nfa, data, chunk, outcap, 1);
                assert_eq!(show(&got), expected, "record nfa={} chunk={} outcap={} endcap=1", nfa, chunk, outcap);
            }
        }
    }
}

#[test]
fn bom_only_and_empty() {
    for &nfa in &[false, true] {
        for chunk in 1..=4 {
            let got = by_field(nfa, b"\xef\xbb\xbf", chunk, 1);
            assert!(got.is_empty(), "bom-only field nfa={} chunk={}: {:?}", nfa, chunk, show(&got));
            let got = by_record(nfa, b"\xef\xbb\xbf", chunk, 1, 1);
            assert!(got.is_empty(), "bom-only record");
            let got = by_field(nfa, b"", chunk, 1);
            assert!(got.is_empty());
            let got = by_record(nfa, b"", chunk, 1, 1);
            assert!(got.is_empty());
        }
    }
}

#[test]
fn partial_prefix_then_eof_is_data() {
    // Just EF, and EF BB, must be retained as data.
    for &data in &[&[0xEFu8][..], &[0xEF, 0xBB][..]] {
        for &nfa in &[false, true] {
            for chunk in 1..=3 {
                let got = by_field(nfa, data, chunk, 1);
                assert_eq!(show(&got), vec![vec![String::from_utf8_lossy(data).to_string()]],
                    "field data={:x?} nfa={} chunk={}", data, nfa, chunk);
                let got = by_record(nfa, data, chunk, 1, 1);
                assert_eq!(show(&got), vec![vec![String::from_utf8_lossy(data).to_string()]],
                    "record data={:x?}", data);
            }
        }
    }
}

#[test]
fn prefix_then_mismatch_data() {
    // EF BB then comma then "x\nok,y\n"
    let mut data = vec![0xEFu8, 0xBB, b',', b'x', b'\n', b'o', b'k', b',', b'y', b'\n'];
    let expected = vec![vec![String::from_utf8_lossy(&[0xEF,0xBB]).to_string(), "x".to_string()],
                        vec!["ok".to_string(), "y".to_string()]];
    for &nfa in &[false, true] {
        for chunk in 1..=10 {
            let got = by_field(nfa, &data, chunk, 1);
            assert_eq!(show(&got), expected, "field nfa={} chunk={}", nfa, chunk);
            let got = by_record(nfa, &data, chunk, 1, 1);
            assert_eq!(show(&got), expected, "record nfa={} chunk={}", nfa, chunk);
        }
    }
    // EF then immediate mismatch: EF 2C ...
    data = vec![0xEF, b',', b'x', b'\n'];
    let expected = vec![vec![String::from_utf8_lossy(&[0xEF]).to_string(), "x".to_string()]];
    for &nfa in &[false, true] {
        for chunk in 1..=4 {
            let got = by_field(nfa, &data, chunk, 1);
            assert_eq!(show(&got), expected, "ef-comma field nfa={} chunk={}", nfa, chunk);
        }
    }
}

