fn by_field(nfa: bool, data: &[u8], chunk: usize, outcap: usize) -> Vec<Vec<Vec<u8>>> {
    let mut b = ReaderBuilder::new();
    b.nfa(nfa);
    let mut rdr = b.build();
    let mut records = vec![];
    let mut row = vec![];
    let mut field = vec![];
    for inp in chunks(data, chunk) {
        let mut out = vec![0u8; outcap];
        // One chunk may require several calls when the output buffer fills.
        let mut pos = 0;
        loop {
