fn by_record(
    nfa: bool,
    data: &[u8],
    chunk: usize,
    outcap: usize,
    endcap: usize,
) -> Vec<Vec<Vec<u8>>> {
    let mut b = ReaderBuilder::new();
    b.nfa(nfa);
    let mut rdr = b.build();
    let mut outbuf = vec![];
    let mut ends = vec![];
    let mut records = vec![];
    for inp in chunks(data, chunk) {
