#[test]
fn split_bom() {
    let data = b"\xef\xbb\xbfname,value\r\n\xe7\x94\xb2,7\r\n";
    let expected = vec![
        vec!["name".to_string(), "value".to_string()],
        vec!["甲".to_string(), "7".to_string()],
    ];
    for &nfa in &[false, true] {
        for chunk in 1..=8 {
            for outcap in 1..=6 {
                let got = by_field(nfa, data, chunk, outcap);
                assert_eq!(show(&got), expected, "field nfa={} chunk={} outcap={}", nfa, chunk, outcap);
                for endcap in 0..=1 {
                    let got = by_record(nfa, data, chunk, outcap, endcap.max(1));
                    assert_eq!(show(&got), expected,
                        "record nfa={} chunk={} outcap={} endcap={}", nfa, chunk, outcap, endcap);
                }
            }
        }
    }
}

#[test]
fn bom_only_and_empty() {
    for &nfa in &[false, true] {
        for chunk in 1..=4 {
            assert!(by_field(nfa, b"\xef\xbb\xbf", chunk, 1).is_empty());
            assert!(by_record(nfa, b"\xef\xbb\xbf", chunk, 1, 1).is_empty());
            assert!(by_field(nfa, b"", chunk, 1).is_empty());
            assert!(by_record(nfa, b"", chunk, 1, 1).is_empty());
        }
    }
}

#[test]
fn partial_prefix_then_eof_is_data() {
    for data in [&[0xEFu8][..], &[0xEF, 0xBB][..]] {
        for &nfa in &[false, true] {
            for chunk in 1..=3 {
                let exp = vec![vec![String::from_utf8_lossy(data).to_string()]];
                assert_eq!(show(&by_field(nfa, data, chunk, 1)), exp, "field");
                assert_eq!(show(&by_record(nfa, data, chunk, 1, 1)), exp, "record");
            }
        }
    }
}

#[test]
fn prefix_then_mismatch() {
    // EF BB , x \n ok , y \n
    let data = [0xEFu8, 0xBB, b',', b'x', b'\n', b'o', b'k', b',', b'y', b'\n'];
    let efbb = String::from_utf8_lossy(&[0xEF, 0xBB]).to_string();
    let expected = vec![
        vec![efbb, "x".to_string()],
        vec!["ok".to_string(), "y".to_string()],
    ];
    for &nfa in &[false, true] {
        for chunk in 1..=10 {
            assert_eq!(show(&by_field(nfa, &data, chunk, 1)), expected, "field chunk={}", chunk);
            assert_eq!(show(&by_record(nfa, &data, chunk, 1, 1)), expected, "record chunk={}", chunk);
        }
    }
    // EF then comma: EF is first field.
    let data = [0xEFu8, b',', b'x', b'\n'];
    let expected = vec![vec![String::from_utf8_lossy(&[0xEF]).to_string(), "x".to_string()]];
    for &nfa in &[false, true] {
        for chunk in 1..=4 {
            assert_eq!(show(&by_field(nfa, &data, chunk, 1)), expected, "ef-comma");
        }
    }
}

#[test]
fn later_bom_is_data() {
    // After a first record, a BOM at the start of a later field is kept.
    let data = b"a\n\xef\xbb\xbfb\n";
    let expected = vec![vec!["a".to_string()], vec!["\u{feff}b".to_string()]];
    for &nfa in &[false, true] {
        for chunk in 1..=9 {
            assert_eq!(show(&by_field(nfa, data, chunk, 1)), expected, "later field chunk={}", chunk);
            assert_eq!(show(&by_record(nfa, data, chunk, 1, 1)), expected, "later record chunk={}", chunk);
        }
    }
}

