use csv_core::{Reader, ReaderBuilder, ReadFieldResult, ReadRecordResult};

fn by_field(nfa: bool, data: &[u8], chunk: usize, outcap: usize) -> Vec<Vec<Vec<u8>>> {
    let mut b = ReaderBuilder::new();
    b.nfa(nfa);
    let mut rdr = b.build();
    let mut records = vec![];
    let mut row = vec![];
    let mut field = vec![];
    let parts = data.chunks(chunk.max(1)).collect::<Vec<_>>();
    let mut idx = 0;
    loop {
        let inp = parts.get(idx).copied().unwrap_or(b"");
        idx += 1;
        let mut pos = 0;
        loop {
            let mut out = vec![0u8; outcap];
            let (res, nin, nout) = rdr.read_field(&inp[pos..], &mut out);
            pos += nin;
            field.extend_from_slice(&out[..nout]);
            match res {
                ReadFieldResult::InputEmpty => break,
                ReadFieldResult::OutputFull => {
                    // Retry the remainder of this chunk with a fresh buffer.
                    assert!(pos < inp.len());
                }
                ReadFieldResult::Field { record_end } => {
                    row.push(std::mem::take(&mut field));
                    if record_end {
                        records.push(std::mem::take(&mut row));
                    }
                    if pos >= inp.len() {
                        break;
                    }
                }
                ReadFieldResult::End => return records,
            }
        }
    }
}

fn by_record(
    nfa: bool,
    data: &[u8],
    chunk: usize,
    outcap: usize,
    endcap: usize,
) -> Vec<Vec<Vec<u8>>> {
    let mut b = ReaderBuilder::new();
    b.nfa(nfa);
    let mut rdr = b.build();
    let mut outbuf = vec![];
    let mut ends = vec![];
    let mut records = vec![];
    let parts = data.chunks(chunk.max(1)).collect::<Vec<_>>();
    let mut idx = 0;
    loop {
        let inp = parts.get(idx).copied().unwrap_or(b"");
        if idx <= parts.len() {
            idx += 1;
        }
        let mut out = vec![0u8; outcap];
        let mut es = vec![0usize; endcap];
        let mut pos = 0;
        loop {
            let (res, nin, nout, nend) =
                rdr.read_record(&inp[pos..], &mut out, &mut es);
            pos += nin;
            outbuf.extend_from_slice(&out[..nout]);
            ends.extend_from_slice(&es[..nend]);
            match res {
                ReadRecordResult::InputEmpty => break,
                ReadRecordResult::OutputFull
                | ReadRecordResult::OutputEndsFull => break,
                ReadRecordResult::Record => {
                    let mut row = vec![];
                    let mut start = 0;
                    for &e in &ends {
                        row.push(outbuf[start..e].to_vec());
                        start = e;
                    }
                    records.push(row);
                    outbuf.clear();
                    ends.clear();
                    if pos >= inp.len() {
                        break;
                    }
                }
                ReadRecordResult::End => return records,
            }
        }
    }
}

fn show(recs: &[Vec<Vec<u8>>]) -> Vec<Vec<String>> {
    recs.iter()
        .map(|r| {
            r.iter()
                .map(|f| String::from_utf8_lossy(f).to_string())
                .collect()
        })
        .collect()
}

#[test]
fn split_bom() {
    let data = b"\xef\xbb\xbfname,value\r\n\xe7\x94\xb2,7\r\n";
    let expected = vec![
        vec!["name".to_string(), "value".to_string()],
        vec!["甲".to_string(), "7".to_string()],
    ];
    for &nfa in &[false, true] {
        for chunk in 1..=8 {
            for outcap in 1..=6 {
                let got = by_field(nfa, data, chunk, outcap);
                assert_eq!(show(&got), expected, "field nfa={} chunk={} outcap={}", nfa, chunk, outcap);
                for endcap in 0..=1 {
                    let got = by_record(nfa, data, chunk, outcap, endcap.max(1));
                    assert_eq!(show(&got), expected,
                        "record nfa={} chunk={} outcap={} endcap={}", nfa, chunk, outcap, endcap);
                }
            }
        }
    }
}

