use std::io::{self, Read};
use csv::{ReaderBuilder, ByteRecord, StringRecord, Position, ErrorKind};
use csv_index::RandomAccessSimple;
use serde::Deserialize;

// A reader whose underlying source yields at most `cap` bytes per fill.
fn small_reader(cap: usize, data: &[u8], headers: bool) -> csv::Reader<SmallCursor<'_>> {
    ReaderBuilder::new()
        .buffer_capacity(cap.max(1))
        .has_headers(headers)
        .from_reader(SmallCursor { buf: data, pos: 0 })
}

struct SmallCursor<'a> { buf: &'a [u8], pos: usize }
impl<'a> io::Read for SmallCursor<'a> {
    fn read(&mut self, out: &mut [u8]) -> io::Result<usize> {
        let n = out.len().min(self.buf.len() - self.pos).min(1.max(out.len()));
        let take = n.min(self.buf.len() - self.pos);
        out[..take].copy_from_slice(&self.buf[self.pos..self.pos + take]);
        self.pos += take;
        Ok(take)
    }
}
impl<'a> io::Seek for SmallCursor<'a> {
    fn seek(&mut self, pos: io::SeekFrom) -> io::Result<u64> {
        match pos {
            io::SeekFrom::Start(p) => { self.pos = p as usize; Ok(p) }
            _ => unreachable!(),
        }
    }
}

#[derive(Deserialize, Debug, PartialEq)]
struct Row { name: String, value: u32 }

const BOM: &[u8] = &[0xEF, 0xBB, 0xBF];

#[test]
fn e2e_bom_headers_serde() {
    let mut data = BOM.to_vec();
    data.extend_from_slice(b"name,value\r\n\xe7\x94\xb2,7\r\n");
    for cap in [1usize, 2, 3, 4, 8, 64] {
        let mut rdr = small_reader(cap, &data, true);
        let headers = rdr.headers().unwrap().clone();
        assert_eq!(headers, vec!["name", "value"], "cap={}", cap);
        let row: Row = rdr.deserialize().next().unwrap().unwrap();
        assert_eq!(row, Row { name: "甲".to_string(), value: 7 }, "cap={}", cap);
        assert!(rdr.deserialize::<Row>().next().is_none(), "cap={}", cap);
    }
}

#[test]
fn e2e_bom_no_headers_two_records() {
    let mut data = BOM.to_vec();
    data.extend_from_slice(b"name,value\r\n\xe7\x94\xb2,7\r\n");
    for cap in [1usize, 2, 3, 5, 64] {
        let mut rdr = small_reader(cap, &data, false);
        let recs: Vec<StringRecord> = rdr.records().map(|r| r.unwrap()).collect();
        assert_eq!(recs.len(), 2, "cap={}", cap);
        assert_eq!(recs[0], vec!["name", "value"]);
        assert_eq!(recs[1], vec!["甲", "7"]);
    }
}

#[test]
fn e2e_bom_only_and_empty() {
    for cap in [1usize, 2, 3, 64] {
        let mut rdr = small_reader(cap, BOM, false);
        assert_eq!(rdr.records().count(), 0, "bom-only cap={}", cap);
        let mut rdr = small_reader(cap, b"", false);
        assert_eq!(rdr.records().count(), 0, "empty cap={}", cap);
    }
}

#[test]
fn e2e_utf8_error_position_stable() {
    // EF BB , x \n ok , y \n
