    for cap in [1usize, 2, 3, 4, 8, 64] {
        let mut rdr = reader(cap, &data, true);
        assert_eq!(rdr.headers().unwrap(), vec!["name", "value"]);
        let row: Row = rdr.deserialize().next().unwrap().unwrap();
        assert_eq!(row, Row { name: "甲".to_string(), value: 7 });
