use csv_core::{ReaderBuilder, ReadFieldResult::*};
// Delimiter set to a BOM byte (0xBB). A genuine BOM is still stripped;
// a rejected prefix is replayed and obeys delimiter semantics.
#[test]
fn bom_byte_as_delimiter() {
    for nfa in [false, true] {
        // genuine BOM then "a<bbdelim>b"
        let mut b = ReaderBuilder::new(); b.nfa(nfa); b.delimiter(0xBB);
        let mut rdr = b.build();
        let mut out = [0u8; 8];
        // feed BOM split: EF, BB, BF, then a <0xBB> b
        let (r,n,_) = rdr.read_field(&[0xEF], &mut out); assert_eq!(r,InputEmpty); assert_eq!(n,1);
        let (r,n,_) = rdr.read_field(&[0xBB], &mut out); assert_eq!(r,InputEmpty); assert_eq!(n,1);
        let (r,n,_) = rdr.read_field(&[0xBF], &mut out); assert_eq!(r,InputEmpty); assert_eq!(n,1);
        let (r,n,no) = rdr.read_field(&[b'a',0xBB,b'b'], &mut out);
        assert_eq!(r, Field{record_end:false}); assert_eq!(n,2); assert_eq!(no,1); assert_eq!(out[0],b'a');
        let (r,n,no) = rdr.read_field(&[b'b'], &mut out);
        assert_eq!(r, Field{record_end:true}); assert_eq!(n,1); assert_eq!(no,1); assert_eq!(out[0],b'b');

        // rejected prefix EF BB <comma instead of BF>
        let mut b = ReaderBuilder::new(); b.nfa(nfa); b.delimiter(0xBB);
        let mut rdr = b.build();
        let _ = rdr.read_field(&[0xEF], &mut out);
        let _ = rdr.read_field(&[0xBB], &mut out);
        // third byte 0x2C mismatches BOM; replay EF then 0xBB(delim) -> field EF ends
        let (r,n,no) = rdr.read_field(&[0x2C, b'z'], &mut out);
        assert_eq!(r, Field{record_end:false}, "nfa={}", nfa); assert_eq!(n,0); assert_eq!(no,1); assert_eq!(out[0],0xEF);
        // next call: the 0x2C byte is still in caller input; 0x2C is ordinary data here
        let (r,n,no) = rdr.read_field(&[0x2C,b'z'], &mut out);
        assert_eq!(r, Field{record_end:true}, "nfa={}",nfa); assert_eq!(n,2); assert_eq!(no,2);
        assert_eq!(&out[..2], &[0x2C,b'z']);
